  "msg.need.water": { en: "The city needs running water: build a Water Works by a road", th: "เมืองต้องการน้ำประปา โปรดสร้างโรงผลิตน้ำประปาติดถนน" },
  "msg.need.more_roads": { en: "More roads required to connect zones", th: "ต้องการถนนเพิ่มเติมเพื่อเชื่อมต่อเมือง" },
