  "era.hint.people": { en: "Paint more homes beside roads: people come where there are water, power and work", th: "ทาเขตที่อยู่อาศัยริมถนนเพิ่ม คนจะย้ายมาเมื่อมีน้ำ ไฟ และงาน" },
  "era.hint.water_village": { en: "Build water towers beside roads: each pumps a little water from its own well. Water works come with the market town", th: "สร้างหอถังประปาติดถนน แต่ละหอสูบน้ำบาดาลได้เล็กน้อย โรงประปามาเมื่อเป็นเมืองตลาด" },
  "era.hint.water": { en: "Build a water works beside a road: water runs in the pipes under every road it reaches. Add another if it runs short", th: "สร้างโรงผลิตน้ำประปาติดถนน น้ำไหลไปตามท่อใต้ถนนที่ต่อถึง ถ้าน้ำไม่พอให้สร้างเพิ่ม" },
  "era.hint.power": { en: "Build a power plant beside a road: power runs along every road it reaches", th: "สร้างโรงไฟฟ้าติดถนน ไฟฟ้าวิ่งไปตามถนนที่ต่อถึง" },
  "era.hint.jobs": { en: "Paint shops and factories so people have work", th: "ทาเขตพาณิชย์และอุตสาหกรรมเพิ่ม ให้คนมีงานทำ" },
  "era.hint.education": { en: "Build schools with seats for the children", th: "สร้างโรงเรียนให้ที่นั่งพอกับเด็ก" },
  "era.hint.education_higher": { en: "Build schools, and a vocational college or university for the young", th: "สร้างโรงเรียน และวิทยาลัยอาชีวะหรือมหาวิทยาลัยให้คนหนุ่มสาว" },
  "era.hint.health": { en: "Build a health centre or a hospital", th: "สร้างโรงพยาบาลส่งเสริมสุขภาพตำบลหรือโรงพยาบาล" },
  "era.hint.safety": { en: "Build police stations near the homes and keep the police budget full", th: "สร้างสถานีตำรวจใกล้ย่านที่อยู่อาศัย และจ่ายงบตำรวจให้เต็ม" },
  "era.hint.clean": { en: "Build enough rubbish sites (landfill, incinerator, recycling) and fewer smoky plants and factories", th: "สร้างที่จัดการขยะให้พอ (ฝังกลบ เตาเผา รีไซเคิล) และลดโรงงานกับโรงไฟฟ้าที่มีควัน" },
  "era.hint.living": { en: "Parks, fair taxes and good services raise land value and please the people", th: "สวน ภาษีที่พอดี และบริการที่ดี ทำให้ที่ดินมีราคาและชาวเมืองพอใจ" },
  "era.hint.symbol": { en: "Build what the era must have, in the list below", th: "สร้างสิ่งที่ยุคต้องมีตามรายการด้านล่าง" },
  "era.symbol_hint.ruler_house": { en: "City & land: the ruler's house, beside a road", th: "หมวดเมืองและที่ดิน: สร้างที่ว่าการ (จวนเจ้าเมือง) ติดถนน" },
  "era.symbol_hint.shops": { en: "Zones: paint shops along the roads until five stand", th: "หมวดเขตเมือง: ทาเขตพาณิชย์ริมถนนจนมีร้าน 5 ร้าน" },
  "era.symbol_hint.water_tower": { en: "Services › Water supply: a water tower beside a road, which pumps its own well", th: "บริการเมือง › ประปา: สร้างหอถังประปาติดถนน สูบน้ำบาดาลเอง" },
  "era.symbol_hint.literate": { en: "Services › Education: a primary school with power; after a year of teaching, a class finishes every January", th: "บริการเมือง › การศึกษา: สร้างโรงเรียนประถมที่มีไฟ สอนครบปีแล้วจะมีนักเรียนจบทุกเดือนมกราคม" },
  "era.symbol_hint.water_works": { en: "Services › Water supply: a water works beside a road", th: "บริการเมือง › ประปา: สร้างโรงผลิตน้ำประปาติดถนน" },
  "era.symbol_hint.power_plant": { en: "Services › Power plant: any kind, beside a road", th: "บริการเมือง › โรงไฟฟ้า: แบบใดก็ได้ ติดถนน" },
  "era.symbol_hint.school": { en: "Services › Education: any school", th: "บริการเมือง › การศึกษา: โรงเรียนแบบใดก็ได้" },
  "era.symbol_hint.hospital": { en: "Services › Healthcare: a hospital (it may need a higher ruler's house first)", th: "บริการเมือง › สาธารณสุข: โรงพยาบาล (อาจต้องยกระดับที่ว่าการก่อน)" },
  "era.symbol_hint.secondary_school": { en: "Services › Education: a secondary school or higher (needs a higher ruler's house)", th: "บริการเมือง › การศึกษา: โรงเรียนมัธยมขึ้นไป (ต้องยกระดับที่ว่าการก่อน)" },
  "era.symbol_hint.paved_roads": { en: "Raise laterite roads to paved ones with the road upgrade, above the road button", th: "ยกระดับถนนลูกรังเป็นลาดยางด้วยเครื่องมืออัปเกรดถนน เหนือปุ่มถนน" },
  "era.symbol_hint.university_or_metro": { en: "A university (Education), or a metro or high-speed rail station (Public transport)", th: "มหาวิทยาลัย (การศึกษา) หรือสถานีรถไฟฟ้าหรือรถไฟความเร็วสูง (ขนส่งสาธารณะ)" },
  "era.symbol_hint.recycling": { en: "Services › Waste & sewage: a recycling plant", th: "บริการเมือง › ขยะและน้ำเสีย: โรงงานรีไซเคิล" },
  "era.symbol_hint.clean_power": { en: "Make at least half the power plants solar, wind or dams", th: "ให้โรงไฟฟ้าอย่างน้อยครึ่งหนึ่งเป็นแสงอาทิตย์ ลม หรือเขื่อน" },
  "era.dawn": { en: "The city is entering a new era, {era}: its buildings begin to change", th: "เมืองเริ่มเข้าสู่ยุค{era} ตึกบางหลังเริ่มเปลี่ยนโฉม" },
  "congrats.era": { en: "{name} has entered a new era: {era}!", th: "{name} เข้าสู่ยุคใหม่: {era}!" },
