  "festival.ask.songkran": { en: "Songkran is next month: families come home and the whole town throws water. How will the city hold it?", th: "เดือนหน้าถึงสงกรานต์ ลูกหลานกลับบ้าน เล่นน้ำกันทั้งเมือง จะจัดงานอย่างไร" },
  "festival.ask.loy_krathong": { en: "Next month's full moon is Loy Krathong: krathong float on the canals and rivers. How will the city hold it?", th: "เดือนหน้าวันเพ็ญเดือนสิบสอง ลอยกระทงริมคลองและแม่น้ำ จะจัดงานอย่างไร" },
  "festival.ask.yi_peng": { en: "Yi Peng is next month: sky lanterns rise into the night. How will the city hold it?", th: "เดือนหน้ายี่เป็ง ปล่อยโคมลอยขึ้นฟ้ายามค่ำ จะจัดงานอย่างไร" },
  "festival.ask.bun_bang_fai": { en: "Bun Bang Fai is next month: rockets ask the sky for the rains. How will the city hold it?", th: "เดือนหน้าบุญบั้งไฟ จุดบั้งไฟขอฝนต้นฤดู จะจัดงานอย่างไร" },
  "festival.ask.silk": { en: "Khon Kaen's silk festival and Phuk Siao are next month. How will the city hold them?", th: "เดือนหน้าเทศกาลไหมและประเพณีผูกเสี่ยวของขอนแก่น จะจัดงานอย่างไร" },
  "festival.ask.vegetarian": { en: "The vegetarian festival is next month: processions and firecrackers. How will the city hold it?", th: "เดือนหน้าเทศกาลกินเจ มีขบวนแห่และจุดประทัด จะจัดงานอย่างไร" },
