  "festival.news.by_people": { en: "{name}: the treasury is empty, so the temples and the people hold it themselves", th: "{name}: เงินในคลังไม่พอ วัดและชาวบ้านจัดกันเอง" },
  "festival.news.downgraded": { en: "{name}: not enough money for a grand festival, so it is held modestly ({cost})", th: "{name}: เงินไม่พอจัดยิ่งใหญ่ จึงจัดแบบเรียบง่าย ({cost})" },
